import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.ItemRegistry{Items: []protocol.ItemEntry{{Name: "minecraft:stick", RuntimeID: 320, ComponentBased: false,
# Version: 0}, {Name: "custom:widget", RuntimeID: -1, ComponentBased: true, Version: 1,
# Data: map[string]any{"minecraft:max_stack_size": int32(16)}}}}
ITEMS = bytes.fromhex(
    "020f6d696e6563726166743a737469636b400100000a00000d637573746f6d3a776964676574ffff01020a0003186d696e65637261"
    "66743a6d61785f737461636b5f73697a652000"
)

# generated by gophertunnel b8bd735:
# &packet.ItemRegistry{}
EMPTY = bytes.fromhex("00")

GOLDENS = [
    pytest.param(
        v2225.ItemRegistryPacket(
            items=[
                v2225.ItemData(
                    name="minecraft:stick",
                    id=320,
                    is_component_based=False,
                    item_version=v2225.ItemVersion.LEGACY,
                ),
                v2225.ItemData(
                    name="custom:widget",
                    id=-1,
                    is_component_based=True,
                    item_version=v2225.ItemVersion.DATA_DRIVEN,
                    component_data=v2225.nbt.CompoundTag({"minecraft:max_stack_size": v2225.nbt.IntTag(16)}),
                ),
            ]
        ),
        ITEMS,
        id="two-items",
    ),
    pytest.param(v2225.ItemRegistryPacket(), EMPTY, id="empty"),
]


def test_item_registry_is_packet_162():
    assert v2225.PACKETS[162] is v2225.ItemRegistryPacket


def test_item_registry_is_one_type_across_the_two_eras():
    assert v1001.PACKETS[162] is v2168.PACKETS[162]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_item_registry_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_item_registry_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
